ites as $invite):?><?php $listedPermissions=array_map(static fn(string $permission):string=>$permissionLabels[$permission]??$permission,array_filter(explode(',',(string)$invite['permissions'])));?><li><span><strong><?=$e($invite['invited_email'])?></strong><small><?=$e($statusLabels[$invite['status']]??$invite['status'])?> · <?=$e(implode(', ',$listedPermissions))?></small></span><?php if(in_array($invite['status'],['pending','accepted'],true)):?><form method="post" action="/minha-conta/perfil/convite/revogar"><?=$hidden('permissoes')?><input type="hidden" name="invite_id" value="<?=(int)$invite['id']?>"><button class="finance-button" type="submit">Revogar</button></form><?php endif;?></li><?php endforeach;?></ul><?php endif;?></section></section>

